from pathlib import Path
import json,html,statistics,hashlib,csv,time
R=Path(__file__).resolve().parent;O=R/'results';read=lambda p:json.loads(p.read_text());s=read(O/'summary.json');coverage=read(O/'coverage.json');journal=read(R/'JOURNAL_AUDIT.json');sensitivity=read(O/'journal_sensitivity.json');partial=read(R/'frozen/two_nn_partial_summary.json')
NAMES={'qwen':'Qwen 27B','gemma':'Gemma 31B','qwen122':'Qwen 122B','mistral':'Mistral','olmo':'OLMo','glm':'GLM','claude4.8-opus':'Claude 4.8 Opus (API alias)','claude4.5-sonnet':'Claude 4.5 Sonnet (API alias)','gpt-astra':'GPT-Astra (API alias)','gpt-4o':'GPT-4o (API alias)'}
def table(scope,policy):
 rows=[r for r in s if r['scope']==scope and r['policy']==policy];out='<table><thead><tr><th>Judge</th><th>No explanation F1</th><th>Saliency F1</th><th>1-NN F1</th><th>NN change (pp)</th><th>NN precision</th><th>NN recall</th><th>Validation n</th><th>Test n</th></tr></thead><tbody>'
 for m in sorted({r['model'] for r in rows}):
  d={r['condition']:r for r in rows if r['model']==m};nn=d['nearest'];out+='<tr>'+''.join('<td>'+html.escape(str(v))+'</td>' for v in [NAMES[m],*[f'{100*d[c]["f1"]:.2f}' for c in ['baseline','saliency','nearest']],f'{100*(nn["f1"]-d["baseline"]["f1"]):+.2f}',f'{100*nn["precision"]:.2f}',f'{100*nn["recall"]:.2f}',f'{nn["validation_n"]:,}',f'{nn["test_n"]:,}'])+'</tr>'
 return out+'</tbody></table>'
parts=['<!doctype html><html><head><meta charset="utf-8"><title>API and local judge results</title><style>body{font:16px system-ui;color:#15202b;max-width:1400px;margin:36px auto;padding:0 20px;line-height:1.5}h1,h2{line-height:1.2}table{border-collapse:collapse;width:100%;font-size:14px;margin:16px 0 30px}th,td{padding:9px;border-bottom:1px solid #d9e1e8;text-align:right}th:first-child,td:first-child{text-align:left}thead{background:#eff4f8}p{max-width:1100px}summary{cursor:pointer;font-weight:600}select{margin:8px;padding:6px}.note{background:#f2f6f9;padding:16px;border-left:4px solid #386b91}</style></head><body><h1>API and local judge results</h1><p>15 October 2026. 600,000 API response rows joined to 900,000 local judgments by frozen prompt ID. All IDs matched; no duplicate response keys. Raw responses and failures are preserved.</p><p class="note">API scores below are conditional on valid responses. Within each API judge, every retained case has a valid probability in all three explanation conditions. The all-judge comparison further uses the identical cases answered by every API judge. Original sampling weights are retained, but the denominator is the matched cohort; these are not full-test API estimates. Missing responses are not assigned labels or recovered by extracting numbers from prose.</p><h2>API judges: largest matched subset within each judge</h2><p>Each entry is an equal average over 5 backbones × 10 datasets. Both probe and judge thresholds are selected on validation data, using the frozen threshold grid and tie rule. Test cases are held out from tuning. Cases can recur across backbones, so n counts backbone-case observations, not unique conversations.</p>',table('api_condition_matched','joint'),'<details><summary>Judge cutoff fixed at 50; probe gate tuned on validation</summary>',table('api_condition_matched','fixed50'),'</details><h2>All ten judges on the same cases</h2><p>18,095 validation and 17,802 test backbone-case observations are shared by all ten judges and all three conditions. Thresholds are retuned on that same matched validation cohort for each judge/condition.</p>',table('common_valid_all_judges','joint'),'<details><summary>Same-case comparison with judge cutoff fixed at 50</summary>',table('common_valid_all_judges','fixed50'),'</details><h2>Original local full-test estimates</h2><p>These preserved results use all original 500 validation and 500 test sampled cases per backbone/dataset and the original population denominators. Their sample scope differs from the API tables above.</p>',table('local_full_test_estimate','joint'),'<h2>Two-neighbour study: completed judges only</h2><p>Qwen and Gemma completed all 100,000 two-NN judgments across five backbones. Values below use the original full sampled design and validation-joint-tuned cutoffs. Mistral stopped before inference because the launcher omitted its parent compatibility environment; that environment was restored on 15 October and the remaining judges resumed. No completed model calls were repeated. This is a partial comparison, not the completed six-judge grid.</p><table><tr><th>Judge</th><th>No explanation F1</th><th>1 NN F1</th><th>2 NN F1</th><th>2 NN minus 1 NN (pp)</th><th>2 NN precision</th><th>2 NN recall</th></tr>']
two=[]
for m in sorted({r['judge'] for r in partial}):
 d={c:{k:statistics.mean(r[k] for r in partial if r['judge']==m and r['condition']==c and r['policy']=='joint') for k in ['f1','precision','recall']} for c in ['baseline','nearest','nearest2']}
 two.append(dict(model=m,**d));parts.append('<tr>'+''.join('<td>'+html.escape(str(v))+'</td>' for v in [NAMES[m],*[f'{100*d[c]["f1"]:.2f}' for c in ['baseline','nearest','nearest2']],f'{100*(d["nearest2"]["f1"]-d["nearest"]["f1"]):+.2f}',f'{100*d["nearest2"]["precision"]:.2f}',f'{100*d["nearest2"]["recall"]:.2f}'])+'</tr>')
parts+=['</table><h2>Coverage and provenance</h2><table><tr><th>API alias</th><th>Valid probabilities</th><th>Invalid/unresolved</th><th>Valid percentage</th><th>Matched cases across conditions</th></tr>']
for r in coverage['models']:parts.append('<tr>'+''.join('<td>'+html.escape(str(v))+'</td>' for v in [r['model'],f'{r["valid_responses"]:,}',f'{r["invalid_responses"]:,}',f'{100*r["valid_responses"]/150000:.2f}%',f'{r["matched_cases"]:,}'])+'</tr>')
parts+=['</table><p>The request journal agrees with every response status and latency. It contains request timestamps and API aliases but no provider model snapshots, exact messages, temperature, reasoning settings or token-limit configuration. Those settings are unverified. There are 15 GPT-Astra keys with repeated dispatch events (14 final valid responses, one ambiguous); excluding every affected case and retuning changes the macro F1 by at most '+f'{sensitivity["max_absolute_macro_f1_change_pp"]:.3f}'+' percentage points.</p><p>Per-cell paired stratified bootstrap intervals use 2,000 resamples and condition on the matched cases and validation-selected thresholds. No pooled significance claim treats different backbones or judges as independent observations. Filtering and missing outputs can change which safety examples remain in the API comparison.</p><h2>Inspect individual datasets and backbones</h2><label>View <select id="scope"><option value="api_condition_matched">API within-judge matched</option><option value="common_valid_all_judges">All judges, same cases</option><option value="local_full_test_estimate">Original local full-test estimates</option></select></label><label>Judge <select id="model"></select></label><label>Backbone <select id="backbone"></select></label><label>Dataset <select id="dataset"></select></label><div id="detail"></div><p><a href="summary.csv">Download summary CSV</a> · <a href="combined_judgments.csv.gz">Download all 1,500,000 joined judgments (CSV gzip)</a> · <a href="paired_comparisons.json">Per-cell paired comparisons</a> · <a href="coverage_by_cell.json">Coverage by dataset/condition</a> · <a href="ANALYSIS_MANIFEST.json">Analysis provenance</a></p>']
data=read(O/'matched_results.json')+read(O/'local_full_results.json');packed=[{k:r[k] for k in ['scope','model','backbone','dataset','condition','policy','f1','precision','recall','validation_n','test_n','probe_threshold','probability_threshold']} for r in data]
parts.append('<script id="data" type="application/json">'+json.dumps(packed).replace('<','\\u003c')+'</script>')
parts.append('''<script>const data=JSON.parse(document.getElementById('data').textContent);const keys=['scope','model','backbone','dataset'];function options(id,items){const s=document.getElementById(id);let v=s.value;s.replaceChildren(...items.map(x=>new Option(x,x)));if(items.includes(v))s.value=v}function render(){const scope=document.getElementById('scope').value;const all=data.filter(r=>r.scope===scope);for(const k of ['model','backbone','dataset'])options(k,[...new Set(all.map(r=>r[k]))].sort());const rs=all.filter(r=>['model','backbone','dataset'].every(k=>r[k]===document.getElementById(k).value));const table=document.createElement('table');const header=table.insertRow();for(const name of ['Condition','Policy','F1','Precision','Recall','Probe cutoff','Judge cutoff','Val n','Test n']){const th=document.createElement('th');th.textContent=name;header.append(th)}for(const r of rs){const row=table.insertRow();for(const x of [r.condition,r.policy,...['f1','precision','recall'].map(k=>(100*r[k]).toFixed(2)),r.probe_threshold.toFixed(6),r.probability_threshold,r.validation_n,r.test_n])row.insertCell().textContent=x}document.getElementById('detail').replaceChildren(table)}for(const k of keys)document.getElementById(k).addEventListener('change',render);render();</script></body></html>''')
(O/'report.html').write_text(''.join(parts));(O/'two_nn_partial.json').write_text(json.dumps(two,indent=2))
# Detailed metrics are a separate scientific data table, preserving numeric types in JSON and CSV.
keys=['scope','source','model','backbone','dataset','condition','policy','validation_n','test_n','probe_threshold','probability_threshold','validation_f1','f1','precision','recall']
with (O/'detailed_metrics.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=keys);w.writeheader();w.writerows({k:r[k] for k in keys} for r in data)
manifest={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in O.iterdir() if p.is_file() and p.name!='COMPLETED.json'}
(O/'COMPLETED.json').write_text(json.dumps(dict(time=time.time(),combined_judgments=1500000,api_judges=4,local_judges=6,full_two_nn_complete=False,files=manifest),indent=2));print('Report complete')
